// =========================================================================
// PRESET SHADER: Neon Mnt Range
// Author: noztol
// Original Link: https://www.shadertoy.com/view/NXBGDR
// License: Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported
// =========================================================================
// This shader renders a volumetric 3D landscape of neon-emissive dunes/mountains.
// Integrated into SurfaceExplorer. Distributed under CC BY-NC-SA 3.0 terms.
// =========================================================================

// Neon Mountains
// By Noztol


float rand1(vec2 p) {
    vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// Procedural Mnts
float terrain(vec2 p) {
    p += vec2(0.0, iTime * 0.2);
    float h = 0.0;
    float a = 1.0;
    mat2 rot = mat2(0.8, -0.6, 0.6, 0.8);

    for(int i = 0; i < 5; i++) {
        vec2 wp = p + vec2(sin(p.y * 0.5), cos(p.x * 0.5));

        float n = 1.0 - abs(sin(wp.x)); 
        n = pow(n, 1.5); // Sharpen the ridges

        h += n * a;
        p = rot * p * 2.0 + vec2(10.0, 5.0);
        a *= 0.45; 
    }
    return h * 0.5 - 1.0; // Scale and shift down
}

// Distance Field Mapping
float map(vec3 p) {
    return p.y - terrain(p.xz);
}

// Calculate realistic surface normals with micro-bump for sand grains
vec3 calcNormal(vec3 p) {
    const vec2 e = vec2(0.005, 0.0); 
    vec3 n = normalize(vec3(
        map(p + e.xyy) - map(p - e.xyy),
        map(p + e.yxy) - map(p - e.yxy),
        map(p + e.yyx) - map(p - e.yyx)
    ));

    // Add high-frequency noise to the normal to simulate individual sand grains
    n.x += (rand1(p.xz * 200.0) - 0.5) * 0.04;
    n.z += (rand1(p.xz * 200.1) - 0.5) * 0.04;
    return normalize(n);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec2 drag = iMouse.z > 0.0 ? iMouse.xy / iResolution.xy : vec2(0.5, 0.2);

    float theta = iTime * 0.1 + drag.x * 6.0;
    float phi   = clamp(1.6 - drag.y * 2.0, 0.1, 1.5);
    float r     = 6.0; 

    vec3 ta = vec3(0.0, -0.5, iTime * 0.2); 
    vec3 ro = ta + r * vec3(sin(phi) * sin(theta), cos(phi), -sin(phi) * cos(theta));

    vec3 ww = normalize(ta - ro);
    vec3 uu = normalize(cross(ww, vec3(0, 1, 0)));
    vec3 vv = cross(uu, ww);
    vec3 rd = normalize(uv.x * uu + uv.y * vv + 2.0 * ww);

    float t = 0.1 + 0.1 * rand1(fragCoord);
    vec3 col = vec3(0.0);
    vec3 glow = vec3(0.0);
    float d = 0.0;
    vec3 p;

    for (int i = 0; i < 150; i++) {
        p = ro + t * rd;
        d = map(p);

        // Volumetric Glow Accumulation (From provided snippet)
        float h = terrain(p.xz);

        // Palette
        vec3 neon = cos(h * 4.0 - iTime + vec3(0.0, 1.5, 3.0)) * 0.5 + 0.5;

        // Only accumulate glow near the higher surface
        if (d < 0.6) {
            glow += neon * 0.003 / (abs(d) + 0.02) * exp(-t * 0.15);
        }

        if (d < 0.001 || t > 30.0) break;
        t += d * 0.6; 
    }


    if (d < 0.001) {
        vec3 n = calcNormal(p);
        vec3 lightDir = normalize(vec3(0.8, 0.4, 0.2)); 

        vec3 albedo = vec3(0.03, 0.02, 0.04); 
        float diff = max(dot(n, lightDir), 0.0);
        float amb = 0.05 + 0.05 * n.y;

        // Specular highlight (very wide/rough for sand)
        vec3 viewDir = normalize(ro - p);
        vec3 halfDir = normalize(lightDir + viewDir);
        float spec = pow(max(dot(n, halfDir), 0.0), 8.0) * 0.05;

        col = albedo * (diff * vec3(0.2, 0.3, 0.5) + amb) + spec;

        // Surface Neon Emission (glows brightest on the dune crests)
        float h = terrain(p.xz);
        vec3 neonBase = cos(h * 4.0 - iTime + vec3(0.0, 1.5, 3.0)) * 0.5 + 0.5;

        // Isolate the crests
        float crestMask = smoothstep(-0.2, 0.5, h);
        col += neonBase * crestMask * 0.4;
    } else {
        // Night sky background
        col = vec3(0.01, 0.02, 0.05) * (1.0 - uv.y);
    }

    col += glow;


    col = mix(col, vec3(0.01, 0.015, 0.03), 1.0 - exp(-t * 0.06));


    col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);

    fragColor = vec4(col, 1.0);
}

