//SOUND_BEGIN
// =========================================================================
// Title: Alien Thorns
// Author: Dave Hoskins
// Source: https://www.shadertoy.com/view/XsSSzD
// License: CC BY-NC-SA 3.0 (Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported)
//
// Note: Adapted for Desktop GLSL Audio. Removed dependencies on iChannel0 
//       and iChannel3. Replaced with mathematical hash functions.
// =========================================================================
// =========================================================================
// Title: Voronoi Thorns Synth
// Note: Adattato per Desktop GLSL Audio. Rimosse le dipendenze da iChannel0 
// e iChannel3. Sostituite con funzioni di hash matematiche.
// =========================================================================

// Alien Thorns Audio - Procedural & RHI Safe Version

#define MOD3 vec3(0.0631, 0.07369, 0.08787)
float gTime;

//--------------------------------------------------------------------------------------------------
vec2 Hash2(vec2 p)
{
    vec3 p3 = fract(vec3(p.xyx) * MOD3);
    p3 += dot(p3.zxy, p3.yxz+19.19);
    return fract(vec2(p3.x * p3.y, p3.z*p3.x));
}

//--------------------------------------------------------------------------------------------------
vec2 Noise( in vec2 x )
{
    return mix(Hash2(floor(x)), Hash2(floor(x)+1.0), fract(x));
}

float Saw(float n, float fil)
{
    float v = 0.0;
    float f = 1.0;
    int filt = int(fil);

    for (int i = 0; i < 100; i++)
    {
        if (i > filt) break;
        float a = 0.5 * (sin(2.0 * f * n * PI) / f);
        if (i > filt - filt/10) a = 2.5 * a;
        v += a;
        f++;
    }
    return v * 2000.0 / (fil + 1000.0);
}

// Sostituzione procedurale della texture iChannel0
vec2 Hash( vec2 n )
{
    vec3 p3 = fract(vec3(n.xyx) * MOD3);
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.xx + p3.yz) * p3.zy);
}

//--------------------------------------------------------------------------
vec2 Noise2D( in vec2 x )
{
    vec2 p = floor(x);
    vec2 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    vec2 res = mix(mix( Hash(p + 0.0), Hash(p + vec2(1.0, 0.0)), f.x),
                   mix( Hash(p + vec2(0.0, 1.0) ), Hash(p + vec2(1.0, 1.0)), f.x), f.y);
    return res - 0.5;
}

//--------------------------------------------------------------------------
vec2 FBM( vec2 p )
{
    vec2 f;
    f  = 0.5000  * Noise2D(p); p = p * 2.32;
    f += 0.2500  * Noise2D(p); p = p * 2.23;
    f += 0.1250  * Noise2D(p); p = p * 2.31;
    f += 0.0625  * Noise2D(p); p = p * 2.28;
    f += 0.03125 * Noise2D(p);
    return f;
}

//--------------------------------------------------------------------------------------------------
vec4 ThornVoronoi( vec3 p)
{
    vec2 f = fract(p.xz);
    p.xz = floor(p.xz);
    float d = 1.0e10;
    vec3 id = vec3(0.0);

    for (int xo = -1; xo <= 1; xo++)
    {
        for (int yo = -1; yo <= 1; yo++)
        {
            // FIX CRITICO RHI: Cast esplicito da int a float
            vec2 g = vec2(float(xo), float(yo));

            // Sostituzione procedurale della texture iChannel3
            vec3 p3 = fract(vec3((p.xz + g + 0.5).xyx) * MOD3);
            p3 += dot(p3, p3.yzx + 19.19);
            vec2 n = fract((p3.xx + p3.yz) * p3.zy);

            n = n * n * (3.0 - 2.0 * n);

            vec2 tp = g + 0.5 + sin(p.y + 1.2831 * (n * gTime * 0.5)) - f;
            float d2 = dot(tp, tp);
            if (d2 < d)
            {
                d = d2;
                id = vec3(tp.x, p.y, tp.y);
            }
        }
    }

    return vec4(id, 1.35 - pow(d, 0.17));
}

//--------------------------------------------------------------------------------------------------
float MapThorns( in vec3 pos )
{
    return pos.y * 0.21 - ThornVoronoi(pos).w  - max(pos.y - 5.0, 0.0) * 0.5 + max(pos.y - 5.5, 0.0) * 0.8;
}

//--------------------------------------------------------------------------------------------------
vec3 Path( float time_in )
{
    return vec3(1.3 + 17.2 * cos(0.2 - 0.5 * 0.33 * time_in * 0.75), 4.7, 7.6 - 16.2 * sin(0.5 * 0.11 * time_in * 0.75) );
}

//--------------------------------------------------------------------------------------------------
// Funzione d'ingresso richiesta dal sintetizzatore di Qt RHI
vec2 mainSound( in int samp, float time_in)
{
    gTime = time_in + 173.0;

    vec3 ro = Path(gTime + 0.0);
    vec3 ta = Path(gTime + 5.2);
    float add = (sin(gTime * 0.3) + 1.0) * 2.0;
    ro.y += add;
    ta.y -= add;

    vec3 cw = normalize(ta - ro);   // Linea di direzione in avanti
    vec3 cp = vec3(0.0, 1.0, 0.0);  // Vettore Up
    vec3 cu = cross(cw, cp);        // Prodotto vettoriale per direzione "orecchio destro"

    vec2 ears;
    ears.x = abs(MapThorns(ro + cu * 0.1)) * 0.8; // Orecchio Sinistro
    ears.y = abs(MapThorns(ro - cu * 0.1)) * 0.8; // Orecchio Destro

    vec2 gain = vec2(0.0);
    gain = clamp(1.0 - ears, 0.0, 1.0);
    gain = pow(gain, vec2(3.9));

    float fil1 = sin(gTime * 0.521) * 50.0 + 60.0;
    float fil2 = -sin(gTime * 0.474) * 50.0 + 60.0;

    vec2 audio;
    audio.x = gain.x * (Saw(11.125 * time_in, fil1) + Saw(22.2 * time_in, fil1));
    audio.y = gain.y * (Saw(11.125 * time_in, fil2) + Saw(22.3 * time_in, fil2));

    vec2 pos = vec2(gTime * 192.017331, gTime * 182.066927);
    pos -= sin(gTime * 0.143) * 20.0 * (gain.x + gain.y);
    audio += FBM(pos) * Saw(gTime * 10.5 - sin(gTime * 0.2) * 8.0, 30.0);

    // Dissolvenza in entrata (se necessaria) e clamping di sicurezza
    return clamp(audio, -1.0, 1.0) * smoothstep(0.0, 2.0, time_in);
}
//SOUND_END

// =========================================================================
// PRESET SHADER: QuasiCrystals - Dragon Eye
// Author: mrange
// Original Link: https://www.shadertoy.com/view/wdXfz8
// License: Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported
// =========================================================================
// This shader combines quasicrystal noise with Fractional Brownian Motion (fBm)
// to simulate the iris texture and electrical volumetric glow of a dragon's eye.
// Integrated into SurfaceExplorer. Distributed under CC BY-NC-SA 3.0 terms.
// =========================================================================

#define PI          3.141592654
#define TAU         (2.0*PI)
#define LAYERS      6
#define FBM         3
#define LIGHTNING   3
#define DISTORT     1.4
#define TIME        iTime
#define TTIME       (TAU*TIME)

float wave(float theta, vec2 p) {
  return (cos(dot(p,vec2(cos(theta),sin(theta)))));
}

float noise(vec2 p, float time) {
  float sum = 0.;
  float a = 1.0;
  for(int i = 0; i < LAYERS; ++i)  {
    float theta = float(i)*PI/float(LAYERS);
    sum += wave(theta, p)*a;
    a*=DISTORT;
  }

  return abs(tanh(sum+1.0+0.75*cos(time)));
}

float fbm(vec2 p, float time) {
  float sum = 0.;
  float a = 1.0;
  float f = 1.0;
  for(int i = 0; i < FBM; ++i)  {
    sum += a*noise(p*f, time);
    a *= 2.0/3.0;
    f *= 2.31;
  }

  return 0.45*(sum);
}

vec3 lightning(vec2 pos, float offset) {
  vec3 col = vec3(0.0);
  vec2 f = vec2(0);

  const float w=0.15;

  for (int i = 0; i < LIGHTNING; i++) {
    float time = TIME + 0.5*float(i);   
    float d1 = abs(offset * w / (0.0 + offset - fbm((pos + f) * 3.0, time)));
    float d2 = abs(offset * w / (0.0 + offset - fbm((pos + f) * 2.0, 0.9 * time + 10.0)));
    col += vec3(clamp(d1, 0.0, 1.0) * vec3(0.1, 0.5, 0.8));
    col += vec3(clamp(d2, 0.0, 1.0) * vec3(0.7, 0.5, 0.3));
  }

  return (col);
}

vec3 postProcess(vec3 col, vec2 q) {
  col=pow(clamp(col,0.0,1.0),vec3(0.75)); 
  col=col*0.6+0.4*col*col*(3.0-2.0*col);  // contrast
  col=mix(col, vec3(dot(col, vec3(0.33))), -0.4);  // satuation
  col*=0.5+0.5*pow(19.0*q.x*q.y*(1.0-q.x)*(1.0-q.y),0.7);  // vigneting
  return col;
}

void rot(inout vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  p = vec2(p.x*c + p.y*s, -p.x*s + p.y*c);
}

vec3 normal(vec2 p, float time) {
  vec2 v;
  vec2 w;
  vec2 e = vec2(0.00001, 0);

  vec3 n;
  n.x = fbm(p + e.xy, time) - fbm(p - e.xy, time);
  n.y = 2.0*e.x;
  n.z = fbm(p + e.yx, time) - fbm(p - e.yx, time);

  return normalize(n);
}

vec3 dragonEye(vec2 p) {
  vec2 pp = 10.0*p;

  rot(p, -0.75); 
  p *= vec2(1.1/tanh(1.0 + length(p)), 1.0);
  float l = length(p);

  float dd = 0.2 + 0.65*(-0.5 + 1.75*(0.5 + 0.5*cos(3.0*l-TTIME/12.0)))*tanh(1.0/((pow(l, 4.0) + 2.0)));
  dd *= smoothstep(9.0, 12.0, TIME-l*2.0);
  vec3 col = vec3(0.0);
  float f = fbm(pp, TIME*0.1);
  vec3 ld = normalize(vec3(p.x, 0.5, p.y));
  vec3 n = normal(pp, TIME*0.1);
  float diff = max(dot(ld, n), 0.0);
  col += vec3(0.5, 1.0, 0.8)*pow(diff, 20.0)/(0.5+dot(p, p));
  col += lightning(pp, dd);
  col *= pow(vec3(f), vec3(1.5, 5.0, 5.0));
//  col += -0.1+0.3*vec3(0.7, 0.2, 0.4)*vec3(tanh((pow(0.6/f, 10))));
  return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 q = fragCoord.xy/iResolution.xy;    
  vec2 p = -1.0 + 2.0*q;

  p.x *= iResolution.x/iResolution.y;    

  vec3 col = dragonEye(p);

  col = postProcess(col, q);

  col *= smoothstep(0.0, 4.0, TIME);

  fragColor = vec4(col, 1.0);  
}
